Read this simplified token contract and, from the code shown alone, say what it lets each caller do: who can create tokens, who can move them, what limits that, and what it records.

```solidity
mapping (address => uint) public balances;
address public owner;
bool public paused;
event Transfer(address from, address to, uint value);

modifier onlyOwner() { require(msg.sender == owner); _; }

function transfer(address to, uint value) public {
    require(!paused);
    require(balances[msg.sender] >= value);
    balances[msg.sender] -= value;
    balances[to] += value;
    emit Transfer(msg.sender, to, value);
}

function seize(address from, address to, uint value) public onlyOwner {
    balances[from] -= value;
    balances[to] += value;
}

function setPaused(bool p) public onlyOwner { paused = p; }
```
